/* ---------- diagnóstico ---------- */
$('#diag').innerHTML=PAINS.map((p,i)=>`<button class="cas" type="button" data-pain="${p.id}" aria-pressed="false"><b>${p.q}</b><span class="row2"><small>Dolor ${i+1}</small><span class="box"></span></span></button>`).join('')+`<button class="cas ally" type="button" data-pain="votos" aria-pressed="false"><b>¿Sabes en qué puesto están los votos que te faltan?</b><span class="row2"><small>Dolor ${PAINS.length+1} · plataforma aliada</small><span class="box"></span></span></button>`;
const painOn=p=>p.mods.every(k=>st.mods.has(k));
const syncPicks=()=>{
 PAINS.forEach(p=>{const on=painOn(p);$$(`[data-pain="${p.id}"]`).forEach(b=>b.setAttribute('aria-pressed',on))});
 $$('.pick[data-mod]').forEach(b=>b.setAttribute('aria-pressed',st.mods.has(b.dataset.mod)));
 $$('[data-pain="votos"],#e3pick').forEach(b=>b.setAttribute('aria-pressed',st.e3));
 const n=PAINS.filter(painOn).length+(st.e3?1:0);$('#planCount').textContent=n;
 const marked=PAINS.filter(painOn);$('#diagOut').innerHTML=n?`<span>Marcaste <b>${n}</b> ${n==1?'dolor':'dolores'}. Sigue marcando; cuando termines, mira cada solución:</span> ${marked.map(p=>`<a class="btn sm" href="#p-${p.id}">${p.short}</a>`).join('')}${st.e3?'<a class="btn sm" href="#e360">Datos electorales</a>':''}<a class="btn sm solid" href="#plan">Ver mi plan</a>`:'<span class="soft">Aún no marcas ninguno. Empieza por el que más te quita el sueño.</span>';
 qdraw();save()};
const togglePain=id=>{if(id=='votos'){st.e3=!st.e3}else{const p=PAINS.find(x=>x.id==id);const on=painOn(p);p.mods.forEach(k=>on?st.mods.delete(k):st.mods.add(k))}syncPicks()};
$('#diag').addEventListener('click',e=>{const b=e.target.closest('.cas');if(!b)return;const id=b.dataset.pain;const was=b.getAttribute('aria-pressed')=='true';togglePain(id);toast(was?'Quitado de tu plan':'Agregado a tu plan')});

