const HOT={1:['Unidad Deportiva','5.900 habilitados','faltan 440 votos','Su puesto más grande: aquí está la mayor tarea',262,150],7:['Colegio San Rafael','3.200 habilitados','faltan 380 votos','35 % de jóvenes: voto nuevo',330,205],10:['Vereda Monteverde','1.400 habilitados','faltan 200 votos','Contrato nuevo de vía: tema clave',160,250]};
const hexSvg=()=>{const s=$('#hexmap'),r=11,w=r*Math.sqrt(3),pts=[];const shade=['#dbe5ff','#c3d4ff','#a3bdff','#7c9ef7','#4f7ae8','#2f5bd0','#1e3f9e'];
 for(let row=0,y=30;y<400;row++,y+=r*1.5)for(let x=40+(row%2)*w/2;x<590;x+=w){const inA=((x-300)/250)**2+((y-215)/165)**2<1,inB=((x-470)/120)**2+((y-250)/80)**2<1;if(!(inA||inB))continue;const d=Math.hypot(x-300,y-150);let lv=d<85?Math.min(6,3+Math.floor(Math.abs(Math.sin(x*.07+y*.11))*4)):0;if(d>=85&&Math.sin(x*.05)*Math.cos(y*.06)>.75)lv=1;pts.push([x,y,lv,d])}
 const hp=(x,y)=>Array.from({length:6},(_,i)=>{const a=Math.PI/180*(60*i-30);return (x+r*.94*Math.cos(a)).toFixed(1)+','+(y+r*.94*Math.sin(a)).toFixed(1)}).join(' ');
 const mk=[[1,262,150],[2,320,128],[3,300,182],[4,342,165],[5,250,190],[6,368,118],[7,330,205],[8,270,108]],sq=[[9,470,210],[10,160,250],[11,420,320],[12,280,360]];
 s.innerHTML=pts.map(p=>`<polygon points="${hp(p[0],p[1])}" fill="${shade[0]}" data-f="${shade[p[2]]}" data-d="${p[3]}"/>`).join('')+`<circle cx="300" cy="155" r="88" fill="none" stroke="#475569" stroke-width="2" stroke-dasharray="6 5"/>`+mk.map(m=>`<g class="${HOT[m[0]]?'hs':''}" data-h="${m[0]}">${HOT[m[0]]?`<circle class="ring" cx="${m[1]}" cy="${m[2]}" r="11"/>`:''}<title>Puesto ${m[0]} · casco urbano</title><circle cx="${m[1]}" cy="${m[2]}" r="11" fill="#0f172a" stroke="#fff" stroke-width="2"/><text x="${m[1]}" y="${m[2]+4}" text-anchor="middle" fill="#fff" font-size="11" font-weight="800" font-family="Archivo,sans-serif">${m[0]}</text></g>`).join('')+sq.map(m=>`<g class="${HOT[m[0]]?'hs':''}" data-h="${m[0]}">${HOT[m[0]]?`<circle class="ring" cx="${m[1]}" cy="${m[2]}" r="11"/>`:''}<title>Puesto ${m[0]} · vereda</title><rect x="${m[1]-11}" y="${m[2]-11}" width="22" height="22" rx="4" fill="#0f172a"/><text x="${m[1]}" y="${m[2]+4}" text-anchor="middle" fill="#fff" font-size="11" font-weight="800" font-family="Archivo,sans-serif">${m[0]}</text></g>`).join('')};
hexSvg();
