 if(e.target.id=='runAg'){const ags=$$('.agent');const lines=['Reporte de la mañana','3 noticias nuevas sobre vías.','Contrato nuevo de la alcaldía en la vía Monteverde.','Cédulas: la inscripción cierra el 31 de agosto.','<b>Propuesta:</b> presentar el jueves el plan de vías rurales en Monteverde y Buenos Aires.'];$('#agMsgs').innerHTML=lines.map((l,i)=>`<p${i==0?' style="font-weight:800"':''}>${l}</p>`).join('');ags.forEach((a,i)=>{setTimeout(()=>a.classList.add('busy'),i*260);setTimeout(()=>a.classList.remove('busy'),i*260+700)});$$('#agMsgs p').forEach((p,i)=>setTimeout(()=>p.classList.add('in'),reduce?0:AG.length*260+i*380))}
