/* E360 dinámico */
const showHot=k=>{const d=HOT[k],el=$('#hot');if(!d)return;el.innerHTML=`<b>Puesto ${k} · ${d[0]}</b>${d[1]}<strong>${d[2]}</strong>${d[3]}`;const L=d[4]/620*100,T=d[5]/420*100;el.style.left=(L>55?L-40:L+4)+'%';el.style.top=(T>60?T-34:T+6)+'%';el.classList.add('on')};
let hotI=0,hotT;const hotCycle=()=>{clearInterval(hotT);const ks=Object.keys(HOT);showHot(ks[0]);hotT=setInterval(()=>{hotI=(hotI+1)%ks.length;showHot(ks[hotI])},3200)};
$('#hexmap').addEventListener('click',e=>{const g=e.target.closest('.hs');if(g){clearInterval(hotT);showHot(g.dataset.h)}});
