const countUp=()=>$$('#e3panel [data-count]').forEach(el=>{const to=+el.dataset.count;if(reduce){el.textContent=to.toLocaleString('es-CO');return}const t0=performance.now();const f=t=>{const k=Math.min(1,(t-t0)/1100);el.textContent=Math.round(to*(1-(1-k)**3)).toLocaleString('es-CO');if(k<1)requestAnimationFrame(f)};requestAnimationFrame(f)});
