const startTour=()=>{clearInterval(tourT);tourStep();tourT=setInterval(()=>{if(!tourOn)return clearInterval(tourT);tourI=(tourI+1)%TK.length;e3cur=TK[tourI];$$('#e3seg button').forEach(x=>x.setAttribute('aria-pressed',x.dataset.k==e3cur));e3draw();tourStep()},7000)};
