/* ---------- plan ---------- */
$('#opts').innerHTML=MOD.map(m=>`<label class="opt"><input type="checkbox" value="${m.k}"><span>${m.n}<small>${m.q}</small></span><em id="e-${m.k}"></em></label>`).join('')+`<label class="opt"><input type="checkbox" value="e360"><span>Estrategia 360 (plataforma aliada)<small>Datos electorales, meta por puesto, tablero y agentes</small></span><em>según territorio</em></label>`;
let lastTotal=0,lastLines=[];
function qdraw(){const sc=+$('#scale').value,mo=+$('#months').value;$('#mOut').textContent=mo;const r=x=>Math.round(x*sc/1e5)*1e5;let once=0,mens=0,L=[];
 $$('#opts input').forEach(c=>{if(c.value=='e360'){c.checked=st.e3;return}const m=MK[c.value];c.checked=st.mods.has(m.k);$('#e-'+m.k).textContent=M(r(m.p))+(m.m?' / mes':'')});
 MOD.filter(m=>!m.m&&st.mods.has(m.k)).forEach(m=>{once+=r(m.p);L.push([m.n,r(m.p),''])});
 const combo=st.mods.has('piezas_s')&&st.mods.has('video_s');
 if(combo){mens+=r(COMBO);L.push(['Contenido gráfico y audiovisual (combo)',r(COMBO),'/mes'])}
 MOD.filter(m=>m.m&&st.mods.has(m.k)&&!(combo&&(m.k=='piezas_s'||m.k=='video_s'))).forEach(m=>{mens+=r(m.p);L.push([m.n,r(m.p),'/mes'])});
 const t=once+mens*mo;
 $('#total').textContent=fmt(t);
 $('#perMonth').textContent=L.length?`${once?`Productos ${M(once)} en pago único`:''}${once&&mens?' + ':''}${mens?`servicios ${M(mens)} al mes × ${mo} ${mo==1?'mes':'meses'}`:''}`:'Marca un dolor o agrega productos y servicios para armar tu plan';
 $('#lines').innerHTML=L.map(l=>`<div><span>${l[0]}</span><span>${M(l[1])}${l[2]}</span></div>`).join('')+(st.e3?'<div><span>Estrategia 360</span><span>se cotiza aparte</span></div>':'')+((st.mods.has('piezas_s')^st.mods.has('video_s'))?'<div><span style="color:#ffe14d">Suma el otro servicio de contenido y los dos quedan en un solo precio</span><span></span></div>':'');
 lastTotal=t;lastLines=L.map(l=>[l[0],l[1]]);setMsg()}
$('#opts').addEventListener('change',e=>{const v=e.target.value;if(v=='e360')st.e3=e.target.checked;else e.target.checked?st.mods.add(v):st.mods.delete(v);syncPicks()});
